using Essco.Application.Customers;
using Essco.Application.Payroll;
namespace Essco.Tests.Unit.Payroll;

public sealed class PayrollSapTests
{ [Fact] public async Task Processor_rejects_unknown_operation() { var p = new PayrollSapJobProcessor(new Repo(null), new Gateway()); var r = await p.ProcessAsync("Other", "{}", default); Assert.False(r.Succeeded); Assert.False(r.Retryable); } [Fact] public async Task Processor_sends_stored_procedure_journal() { var journal = new PayrollJournal(8, "Planilla", [new("5000", 100, 0), new("1000", 0, 100)]); var gateway = new Gateway(); var p = new PayrollSapJobProcessor(new Repo(journal), gateway); var r = await p.ProcessAsync(PayrollSapOperations.CreateJournal, "{\"Number\":8}", default); Assert.True(r.Succeeded); Assert.Equal(8, gateway.Journal!.Number); } private sealed class Repo(PayrollJournal? value) : IPayrollJournalRepository { public ValueTask<PayrollJournal?> GetAsync(int n, CancellationToken t) => ValueTask.FromResult(value); } private sealed class Gateway : ISapPayrollGateway { public PayrollJournal? Journal { get; private set; } public ValueTask<SapProcessingResult> CreateJournalAsync(PayrollJournal j, CancellationToken t) { Journal = j; return ValueTask.FromResult(new SapProcessingResult(true, "12", null, false)); } } }
